# e verifica che ogni prova citata esista. I valori sono quelli delle letture (prove/<ID>/lettura-*.json, script/misure-script.json,
# effetti-misurati.tsv) e delle foto; la prosa sta in «descrizione». Uso: python3 -I visita4-osservazioni.py
import json, os, re, sys
RIC = '/workspace/kalliope/design/ricerca'
mancanti = []

def parole(t): return len(re.findall(r"[A-Za-zÀ-ÿ0-9'’\-]+", t))
def frasi(t): return len([f for f in re.split(r'(?<=[\.\!\?])\s+', t.strip()) if f])

def o(car, amb, ev=None, valore=None, desc=None, nonmis=None, stato='presente', motivo=None):
    r = {'caratteristica': car, 'ambito': amb, 'stato': stato}
    if stato == 'non_osservato':
        r['motivo'] = motivo; return r
    r['evidenze'] = ev or []
    if stato == 'presente': r['valore'] = valore
    if nonmis: r['non_misurati'] = nonmis
    if desc: r['descrizione'] = desc
    for e in r['evidenze']:
        if not os.path.exists(os.path.join(RIC, e.split('#')[0])): mancanti.append(e)
    return r

def assente(car, amb, ev, desc): return o(car, amb, ev, desc=desc, stato='assente')
def nonoss(car, amb, motivo): return o(car, amb, stato='non_osservato', motivo=motivo)

def eff(id_, amb_extra, trigger, durata, curva, prop, ev, desc, nonmis=None, ambito='arrivo computer'):
    v = {'trigger': trigger}
    if durata is not None: v['durata_ms'] = durata
    if curva is not None: v['curva'] = curva
    if prop is not None: v['proprieta'] = prop
    return o('effetto o animazione', f'{ambito} · {amb_extra}', ev, v, desc, nonmis)

